    value?: 'bad_authorization' | 'token_expired' | 'token_revoked' | 'application_not_found' | 'manager_extra_account_not_found' | 'used_manager_account_forbidden' | 'user_auth_expected' | 'application_auth_expected' | 'employer_on_additional_check_restricted';
